import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Link } from 'react-router-dom';

function Home() {
  const [featuredMeals, setFeaturedMeals] = useState([]);

  useEffect(() => {
    fetchFeaturedMeals();
  }, []);

  const fetchFeaturedMeals = async () => {
    try {
      const meals = [
        { name: 'Grilled Veggie Salad', calories: 500, image: 'https://via.placeholder.com/200?text=Veggie+Salad', nutrition: { protein: 10, carbs: 20, fat: 5 } },
        { name: 'Chicken Stir-Fry', calories: 600, image: 'https://via.placeholder.com/200?text=Chicken+Stir-Fry', nutrition: { protein: 25, carbs: 15, fat: 10 } },
      ];
      setFeaturedMeals(meals);
    } catch (error) {
      console.error('Failed to fetch featured meals:', error);
    }
  };

  return (
    <div style={{ padding: '20px', textAlign: 'center', background: '#000000', color: '#ff0000' }}>
      <h1>Welcome to MealMind</h1>
      <p style={{ color: '#ff0000' }}>Discover delicious, personalized meal plans with AI-powered suggestions!</p>
      <div style={{ display: 'flex', justifyContent: 'center', flexWrap: 'wrap', gap: '20px', marginTop: '20px' }}>
        {featuredMeals.map((meal, index) => (
          <div key={index} style={{ border: '2px solid #ff0000', padding: '10px', borderRadius: '8px', width: '200px', background: '#000000', color: '#ff0000' }}>
            <img src={meal.image} alt={meal.name} style={{ width: '100%', borderRadius: '4px' }} />
            <h3>{meal.name}</h3>
            <p>{meal.calories} kcal</p>
            <p>Protein: {meal.nutrition.protein}g, Carbs: {meal.nutrition.carbs}g, Fat: {meal.nutrition.fat}g</p>
          </div>
        ))}
      </div>
      <p style={{ marginTop: '20px', color: '#ff0000' }}>
        <Link to="/signin" style={{ color: '#ff0000', textDecoration: 'underline' }}>Sign in</Link> to explore more features, or try our <button onClick={() => alert('AI suggesting recipes... Coming soon!')} style={{ background: '#ff0000', color: 'white', border: 'none', padding: '5px 10px', borderRadius: '4px', cursor: 'pointer' }}>AI Suggestions</button>!
      </p>
      <button onClick={() => alert('Settings coming soon!')} style={{ background: '#ff0000', color: 'white', border: 'none', padding: '5px 10px', marginTop: '10px', borderRadius: '4px', cursor: 'pointer' }}>App Settings</button>
    </div>
  );
}

export default Home;
